-- L23-l1-otakudle-first-adaptation.sql (lane otkdata, run O1, audit 06 of 2026-11-08 validated by the owner on 2026-11-09; generated by scripts/anime/a2/corrections/gen.mjs from spec-l23.mjs, do not edit by hand)
--
-- What:   Otakudle studio = the studio of the first TV adaptation (D-5), year = first publication of the original work, in any form (D-6).
--         1. series_facts.first_studios text[] (nullable, additive); the view dle_src_anime_character (L18's text) reads coalesce(sf.first_studios, fs.studios), so L04's studios, which describe later seasons too, stay untouched.
--            Hunter x Hunter {Nippon Animation} (the 1999 series; the five featured characters Gon, Killua, Kurapika, Chrollo and Hisoka were Madhouse), Fruits Basket {Studio Deen} (the 2001 series; Tohru Honda was TMS Entertainment).
--         2. series.anime_start_year (L04): Hunter x Hunter 2011 -> 1999, Fruits Basket 2019 -> 2001 (guarded on the old value).
--         3. series_facts.work_year (the override L18 added): Apothecary Diaries 2011, Slime 2013, Solo Leveling 2016, Omniscient Reader 2018.
--            Apothecary Diaries, Slime, Solo Leveling and Omniscient Reader move to the web novel; the other 46 series were checked against the same rule and keep their year: manga and light-novel series start with the serialisation or the first volume, the original anime (Code Geass, Cowboy Bebop, Evangelion) with the broadcast, and Re:Zero 2012, Sword Art Online 2002, Mob Psycho 100 2012, Steins;Gate 2009, One-Punch Man 2009 are L18's.
--         4. entity_sources: one row per value (field otakudle.work_year, otakudle.first_studios, otakudle.anime_start_year), source_ref = the revision id read on 2026-11-09. The English Wikipedia page of The Apothecary Diaries
--            does not date the web novel, so its year rests on the Fandom page (revision 17930: since 2011 on Shosetsuka ni Naro).
--         Nothing else: no other series, no kpop row.
-- Needs:  019, 023, L04, L13, L18 (series_facts.work_year and the view it replaced; this file replaces the view again starting from L18's text). Apply after L22 (any order works).
-- WHEN:   apply by the owner after a backup, just after 00:30 UTC, never between 23:50 and 00:30 UTC, never during a build. The file refreshes the snapshot and then reads dle_schedule for today and the next 7 days:
--         if a scheduled answer (or the answer served today) stopped being a possible answer, the file aborts and nothing is written (none is expected: only studio and year values move).
-- Undo:   L23-l1-otakudle-first-adaptation.rollback.sql (the view of L18, the old values, the sources, the column).
-- o1-transaction: single, ONE DO block (atomic on its own, in psql and in the Supabase SQL Editor). Idempotent: a second run changes nothing; a row that already moved to another value is left alone.

do $o1l23$
begin
perform set_config('lock_timeout', '5s', true);
perform set_config('client_min_messages', 'warning', true);


begin
  if to_regclass('public.series_facts') is null or not exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'series_facts' and column_name = 'work_year') then
    raise exception 'L23: L18 must be applied first (series_facts.work_year)';
  end if;
  if (select count(*) from public.groups g join public.series_facts sf on sf.group_id = g.id where g.site_id = 'anime' and g.slug in ('apothecary-diaries', 'that-time-i-got-reincarnated-as-a-slime', 'solo-leveling', 'omniscient-readers-viewpoint', 'hunter-x-hunter', 'fruits-basket')) <> 6 then
    raise exception 'L23: a series_facts row is missing (apply L13 first)';
  end if;
end;

-- 1. The override of the studio: the studios of the first TV adaptation, read before the studios of L04 (which describe the later seasons too).
alter table public.series_facts add column if not exists first_studios text[] check (first_studios is null or cardinality(first_studios) between 1 and 6);

-- 2. The view of the game: L18's, with coalesce(sf.first_studios, fs.studios).
create or replace view public.dle_src_anime_character with (security_invoker = true) as
with first_studio as (
  select s.group_id,
    coalesce(
      nullif(array(
        select distinct case when e ->> 'name' = 'Studio Pierrot' then 'Pierrot' else e ->> 'name' end
        from jsonb_array_elements(s.studios) as e
        where (e -> 'seasons') @> '[1]'::jsonb
      ), '{}'),
      nullif(array(
        select distinct case when e ->> 'name' = 'Studio Pierrot' then 'Pierrot' else e ->> 'name' end
        from jsonb_array_elements(s.studios) as e
        where coalesce(jsonb_array_length(case when jsonb_typeof(e -> 'seasons') = 'array' then e -> 'seasons' end), 0) = 0
      ), '{}')
    ) as studios
  from public.series s
), pool as (
  select c.id, c.name, c.name_native, c.aliases, c.slug,
    f.gender, f.species, f.role_at_debut, f.first_appearance, f.voice_actor_ja, f.featured,
    g.slug as series_slug, s.title_en, s.aliases as series_aliases, sf.genres,
    nullif(btrim(to_jsonb(s) ->> 'franchise'), '') as franchise,
    coalesce(sf.work_year, case when s.type = 'anime_original' then s.anime_start_year else s.manga_start_year end) as work_year,
    coalesce(sf.first_studios, fs.studios) as studios
  from public.characters c
  join public.character_facts f on f.character_id = c.id
  join public.series s on s.group_id = c.group_id and s.published
  join public.groups g on g.id = c.group_id and g.site_id = 'anime'
  join first_studio fs on fs.group_id = s.group_id
  left join public.series_facts sf on sf.group_id = s.group_id
  where c.status = 'published'
)
select
  p.id::text as entity_id,
  p.name,
  array(select distinct n from unnest(array[p.name, p.name_native, p.title_en] || p.aliases || p.series_aliases) as n where nullif(btrim(n), '') is not null) as search,
  jsonb_build_object(
    'series', jsonb_build_object('v', p.title_en, 'p', case when p.franchise is not null then jsonb_build_array(p.franchise) end),
    'gender', jsonb_build_object('v', p.gender),
    'species', jsonb_build_object('v', p.species),
    'role', jsonb_build_object('v', p.role_at_debut),
    'genres', jsonb_build_object('v', to_jsonb(p.genres)),
    'year', jsonb_build_object('v', p.work_year),
    'studio', jsonb_build_object('v', to_jsonb(p.studios))
  ) as attrs,
  jsonb_strip_nulls(jsonb_build_object('voice_actor_ja', p.voice_actor_ja, 'initial', upper(left(p.name, 1)))) as hints,
  (select ei.thumb_path from public.entity_images ei
    where ei.site_id = 'anime' and ei.kind = 'character' and ei.slug = p.series_slug || '/' || p.slug and ei.license_verified and ei.thumb_path is not null) as thumb_path,
  p.series_slug as balance_key,
  p.featured and p.voice_actor_ja is not null as can_be_target
from pool p;

revoke all on table public.dle_src_anime_character from public, anon, authenticated;
grant select on table public.dle_src_anime_character to service_role;

-- 3. The values, each guarded on the value L04 / L18 hold, with a self-check on the number of rows changed.
declare n integer; m integer;
begin
  update public.series_facts sf set work_year = v.y::smallint
  from (values ('apothecary-diaries', 2011), ('that-time-i-got-reincarnated-as-a-slime', 2013), ('solo-leveling', 2016), ('omniscient-readers-viewpoint', 2018)) as v(slug, y), public.groups g
  where g.site_id = 'anime' and g.slug = v.slug and sf.group_id = g.id and sf.work_year is null;
  get diagnostics n = row_count;
  select count(*) into m from public.series_facts sf join public.groups g on g.id = sf.group_id and g.site_id = 'anime'
    join (values ('apothecary-diaries', 2011), ('that-time-i-got-reincarnated-as-a-slime', 2013), ('solo-leveling', 2016), ('omniscient-readers-viewpoint', 2018)) as v(slug, y) on v.slug = g.slug where sf.work_year = v.y;
  if n > 0 and m <> 4 then raise exception 'L23: work_year: % changed, % at the wanted value, expected 4', n, m; end if;

  update public.series_facts sf set first_studios = v.s
  from (values ('hunter-x-hunter', array['Nippon Animation']::text[]), ('fruits-basket', array['Studio Deen']::text[])) as v(slug, s), public.groups g
  where g.site_id = 'anime' and g.slug = v.slug and sf.group_id = g.id and sf.first_studios is null;
  get diagnostics n = row_count;
  select count(*) into m from public.series_facts sf join public.groups g on g.id = sf.group_id and g.site_id = 'anime'
    join (values ('hunter-x-hunter', array['Nippon Animation']::text[]), ('fruits-basket', array['Studio Deen']::text[])) as v(slug, s) on v.slug = g.slug where sf.first_studios = v.s;
  if n > 0 and m <> 2 then raise exception 'L23: first_studios: % changed, % at the wanted value, expected 2', n, m; end if;

  update public.series s set anime_start_year = 1999 from public.groups g where g.id = s.group_id and g.site_id = 'anime' and g.slug = 'hunter-x-hunter' and s.anime_start_year = 2011;
  update public.series s set anime_start_year = 2001 from public.groups g where g.id = s.group_id and g.site_id = 'anime' and g.slug = 'fruits-basket' and s.anime_start_year = 2019;
end;

-- 4. The sources: one row per value (Wikipedia or Fandom page, source_ref = the revision id read on 2026-11-09).
insert into public.entity_sources (entity_type, entity_id, field, source, source_ref, source_url, fetched_at)
select 'series', s.slug, s.field, s.source, s.ref, s.url, '2026-11-09T00:00:00Z'::timestamptz from (values
    ('apothecary-diaries', 'otakudle.work_year', 'fandom', '17930', 'https://kusuriya.fandom.com/wiki/Kusuriya_no_Hitorigoto'),
    ('that-time-i-got-reincarnated-as-a-slime', 'otakudle.work_year', 'wikipedia', '1381575839', 'https://en.wikipedia.org/wiki/That_Time_I_Got_Reincarnated_as_a_Slime'),
    ('solo-leveling', 'otakudle.work_year', 'wikipedia', '1383622083', 'https://en.wikipedia.org/wiki/Solo_Leveling'),
    ('omniscient-readers-viewpoint', 'otakudle.work_year', 'wikipedia', '1384228095', 'https://en.wikipedia.org/wiki/Omniscient_Reader''s_Viewpoint'),
    ('hunter-x-hunter', 'otakudle.first_studios', 'wikipedia', '1383764628', 'https://en.wikipedia.org/wiki/Hunter_%C3%97_Hunter_(1999_TV_series)'),
    ('hunter-x-hunter', 'otakudle.anime_start_year', 'wikipedia', '1383764628', 'https://en.wikipedia.org/wiki/Hunter_%C3%97_Hunter_(1999_TV_series)'),
    ('fruits-basket', 'otakudle.first_studios', 'wikipedia', '1368461630', 'https://en.wikipedia.org/wiki/Fruits_Basket_(2001_TV_series)'),
    ('fruits-basket', 'otakudle.anime_start_year', 'wikipedia', '1368461630', 'https://en.wikipedia.org/wiki/Fruits_Basket_(2001_TV_series)')
) as s(slug, field, source, ref, url)
on conflict (entity_type, entity_id, field, source) do update set source_ref = excluded.source_ref, source_url = excluded.source_url, fetched_at = excluded.fetched_at
where (entity_sources.source_ref, entity_sources.source_url, entity_sources.fetched_at) is distinct from (excluded.source_ref, excluded.source_url, excluded.fetched_at);

-- The snapshot the players read.
begin
  if exists (select 1 from public.dle_entities where game_id = 'otakudle') then perform public.dle_refresh_entities('otakudle'); end if;
end;

-- Nobody scheduled in the next 7 days, nor today's answer, may have stopped being a possible answer (the whole file is undone if so).
declare r record;
begin
  if to_regclass('public.dle_schedule') is not null and to_regclass('public.dle_games') is not null and to_regclass('public.dle_entities') is not null then
    for r in
      select s.game_id, s.entity_id, s.bank_day from public.dle_games g join public.dle_schedule s on s.game_id = g.id
      join public.dle_entities e on e.game_id = s.game_id and e.entity_id = s.entity_id
      where g.id = 'otakudle' and g.epoch is not null and not (e.can_be_target and e.in_pool)
        and s.bank_day in (select public.dle_bank_day(g.epoch, public.dle_utc_date(now()) + k) from generate_series(0, 7) as k)
    loop
      raise exception 'L23: entity % of % (bank day %) is scheduled in the next 7 days and is no longer a possible answer', r.entity_id, r.game_id, r.bank_day;
    end loop;
    if to_regclass('public.dle_daily_stats') is not null and exists (select 1 from public.dle_daily_stats d join public.dle_entities e on e.game_id = d.game_id and e.entity_id = d.entity_id
       where d.game_id = 'otakudle' and d.play_date >= public.dle_utc_date(now()) and not (e.can_be_target and e.in_pool)) then
      raise exception 'L23: the answer served today is no longer a possible answer';
    end if;
  end if;
end;

notify pgrst, 'reload schema';

end $o1l23$;
